/* Original AI-generated space illustrations. No publisher art or rule-bearing text is baked into the images.
   Shared across Race (original edition + first arc) and Roll (base + Ambition).
   All rules, dice faces, costs, points, positions and labels are drawn by the existing engines. */
(function(){'use strict';
const assets={"novelty":"data:image/webp;base64,","rare":"data:image/webp;base64,","genes":"data:image/webp;base64,","alien":"data:image/webp;base64,","colony":"data:image/webp;base64,","military":"data:image/webp;base64,","consumption":"data:image/webp;base64,","earth":"data:image/webp;base64,","research":"data:image/webp;base64,","factory":"data:image/webp;base64,","port":"data:image/webp;base64,","orbital":"data:image/webp;base64,"};
const world={blue:'novelty',cyan:'novelty',brown:'rare',green:'genes',yellow:'alien',red:'military',purple:'consumption'};
const phase={I:'orbital',II:'research',III:'colony',IV:'port',V:'factory','★':'orbital'};
function select(p){let n=String(p.name||'');if(p.art&&assets[p.art])return p.art;
 if(p.phase)return phase[p.phase]||'orbital';
 if(p.dev||p.kind==='dev'){
  if(/군사|함대|전쟁|점령|반란|제국군|military/i.test(n))return 'military';
  if(/생산|공장|산업|제조|factory/i.test(n))return 'factory';
  if(/소비|명성|prestige|consume/i.test(n))return 'consumption';
  if(/무역|교역|항구|판매|선적|trade|ship/i.test(n))return 'port';
  if(/탐사|우주|궤도|explore/i.test(n))return 'orbital';
  return 'research';
 }
 if(p.military||/군사|정복|반란|함대/.test(n))return 'military';
 if(world[p.color])return world[p.color];
 if(/외계|유적/.test(n))return 'alien';if(/광산|희귀/.test(n))return 'rare';if(/유전자|생물/.test(n))return 'genes';
 return p.startNum===0||/지구|모성/.test(n)?'earth':'colony';
}
function svg(parent,key,x,y,width,height,extra={}){if(!assets[key])return null;
 const i=document.createElementNS('http://www.w3.org/2000/svg','image');
 for(const [k,v] of Object.entries({href:assets[key],x,y,width,height,preserveAspectRatio:'xMidYMid slice','data-rm-galaxy-art':key,...extra}))i.setAttribute(k,v);
 parent.append(i);return i;
}
window.RMGalaxyArt=Object.freeze({assets:Object.freeze(assets),select,svg});
})();
